package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*;import com.exe201.rrms.repository.*;import com.exe201.rrms.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController {private final UserRepository users;private final FollowRepository follows;private final AuthService auth;private final ListingRepository listings;public UserController(UserRepository u,FollowRepository f,AuthService a,ListingRepository l){users=u;follows=f;auth=a;listings=l;} @GetMapping("/{id}/public") public Map<String,Object> pub(@PathVariable Long id){User u=users.findById(id).orElseThrow();Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("fullName",u.getFullName());m.put("avatarUrl",u.getAvatarUrl());m.put("bio",u.getBio());m.put("role",u.getRole());m.put("schoolName",u.getSchoolName());m.put("facebookUrl",u.getFacebookUrl());m.put("zaloUrl",u.getZaloUrl());m.put("otherSocialUrl",u.getOtherSocialUrl());m.put("followers",follows.countByFollowingId(id));m.put("following",follows.countByFollowerId(id));m.put("listings",listings.findByLandlordIdOrderByUpdatedAtDesc(id).stream().filter(x->"ACTIVE".equals(x.getStatus())).toList());return m;} @PostMapping("/{id}/follow") public Map<String,Object> follow(@PathVariable Long id,HttpServletRequest r){User me=auth.current(r);if(me.getId().equals(id))throw new IllegalArgumentException("Không thể tự theo dõi chính mình");var ex=follows.findByFollowerIdAndFollowingId(me.getId(),id);if(ex.isPresent()){follows.delete(ex.get());return Map.of("following",false);}Follow f=new Follow();f.setFollowerId(me.getId());f.setFollowingId(id);follows.save(f);return Map.of("following",true);} }
